t = int(input())
for i in range(t):
	(k, n, l, r) = map(int, input().split())
	a = [sorted(map(int, input().split())) for j in range(k)]
	x = [[sum(a[i])] * 2 for i in range(k)]
	for j in range(n + 1):
		if min((x[z][1] for z in range(k))) >= max((x[z][0] for z in range(k))):
			print(j)
			break
		for y in range(k):
			x[y][1] += r - a[y][j]
			x[y][0] -= a[y][-1 - j] - l
